wg(a){return"\ud398\uc774\uc2a4\uac00 \uc804\ubcf4\ub2e4 "+a+"% \ub290\ub824\uc84c\uc5b4\uc694. \ud53c\ub85c\uac00 \uc313\uc600\uc744 \uc218 \uc788\uc5b4\uc694."},
wl(a){return"\ucd5c\uadfc 3\uac1c\uc6d4 \ub3d9\uc548 \uccb4\uc911\uc774 "+a+"kg \ubcc0\ud588\uc5b4\uc694."},
qu(a){return"\uacc4\ud68d\ud55c \ub0a0\uc744 "+a+"\uc77c \uc5f0\uc18d \uc644\ub8cc\ud588\uc5b4\uc694."},
gzW(){return"\ud50c\ub79c\uc740 \uc774\ub807\uac8c \uc791\ub3d9\ud574\uc694"},
gzV(){return"\ub0b4\uac00 \ud50c\ub79c\uc5d0 \ub9de\ucd94\ub294 \uac8c \uc544\ub2c8\ub77c \ud50c\ub79c\uc774 \ub098\uc5d0\uac8c \ub9de\ucdb0\uc694."},
gzU(){return"\uc9c0\uae08 \uc2e4\ub825\uc5d0\uc11c \uc2dc\uc791\ud574\uc694"},
gzT(){return"\uc624\ub298 \uc5bc\ub9c8\ub098 \ud560 \uc218 \uc788\ub294\uc9c0 \ubb3c\uc5b4\ubd10\uc694. \ud50c\ub79c\uc740 \uc77c\ubc18\uc801\uc778 \uc22b\uc790\uac00 \uc544\ub2c8\ub77c \uac70\uae30\uc11c \uc2dc\uc791\ud574\uc694."},
gzS(){return"\ub2e4\uce58\uc9c0 \uc54a\uace0 \ub298\ub824\uc694"},
gzR(){return"\ubd80\ud558\ub294 \ud55c \uc8fc\uc5d0 \ucd5c\ub300 15%\uae4c\uc9c0\ub9cc \ub298\uace0, 4\uc8fc\ub9c8\ub2e4 \ud55c \uc8fc\ub294 \uac00\ubccd\uac8c \ud574\uc11c \ud68c\ubcf5\ud574\uc694."},
gzM(){return"\ub9e4\uc77c \ub9de\ucdb0\uc11c \uc870\uc815\ub3fc\uc694"},
gzL(){return"\uc6b4\ub3d9 \uc804\uc5d0 \ucee8\ub514\uc158\uc744 \uc54c\ub824 \uc8fc\uc138\uc694. \uadf8\uac83\uacfc \ud53c\ub85c, \uacb0\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \uc624\ub298 \uc138\uc158\uc744 \uc870\uc815\ud558\uace0 \uc774\uc720\ub3c4 \uc54c\ub824 \ub4dc\ub824\uc694."},
gzO(){return"\ub290\ub08c\uc5d0\uc11c \ubc30\uc6cc\uc694"},
gzN(){return"\ub05d\ub098\uba74 \uc5bc\ub9c8\ub098 \ud798\ub4e4\uc5c8\ub294\uc9c0 \ud45c\uc2dc\ud574\uc694. \uadf8\uac78\ub85c \uc5ec\uc720\uac00 \uc5bc\ub9c8\ub098 \ub0a8\uc558\ub294\uc9c0 \uc54c\uace0 \ub2e4\uc74c\uc744 \ub2e4\ub4ec\uc5b4\uc694."},
gzK(){return"\ud070 \ubcc0\uacbd\uc740 \uc9c1\uc811 \uacb0\uc815\ud574\uc694"},
gzJ(){return"\uc2e4\uc81c \ud398\uc774\uc2a4\uac00 \ud50c\ub79c\uc5d0\uc11c \ubc97\uc5b4\ub098\uba74 \uc0c8 \ub0a0\uc9dc\ub97c \uc81c\uc548\ud574\uc694. \ubb3b\uc9c0 \uc54a\uace0 \ubaa9\ud45c\ub97c \ubc14\uafb8\ub294 \uc77c\uc740 \uc5c6\uc5b4\uc694."},
gzQ(){return"\ub370\uc774\ud130\ub294 \ud734\ub300\ud3f0 \ubc16\uc73c\ub85c \ub098\uac00\uc9c0 \uc54a\uc544\uc694"},
gzP(){return"\ubaa8\ub4e0 \uacc4\uc0b0\uacfc \uc800\uc7a5\uc740 \uae30\uae30 \uc548\uc5d0\uc11c \uc774\ub904\uc838\uc694. \uacc4\uc815\ub3c4 \ud074\ub77c\uc6b0\ub4dc\ub3c4 \uc5c6\uc5b4\uc694."},
gri(){return"\uc54c\uaca0\uc5b4\uc694"},
gyT(){return"\uc790\uc138\ud788 \uc54c\uc544\ubcf4\uae30"},
goT(){return"\ud50c\ub79c \uc791\ub3d9 \ubc29\uc2dd"},
goS(){return"\ub4a4\ub85c"},
gyJ(){return"Road To\ub294 \uc7a5\uae30 \ud50c\ub79c\uacfc \ub9e4\uc77c\uc758 \uc870\uc815\uc744 \uacb0\ud569\ud574\uc694. \ud50c\ub79c\uc740 \ubaa9\ud45c\uae4c\uc9c0\uc758 \uae38\uc744 \uc815\ud558\uace0, \ub9e4\uc77c\uc758 \uc870\uc815\uc740 \uac01 \uc138\uc158\uc744 \uadf8\ub0a0 \uc0c1\ud0dc\uc5d0 \ub9de\ucdb0\uc694. \ubaa8\ub4e0 \uacc4\uc0b0\uc740 \ud734\ub300\ud3f0\uc5d0\uc11c \uc774\ub904\uc838\uc694."},
gyS(){return"\uc624\ub298 \ubcf4\uc774\ub294 \uac83"},
gyO(){return"\ucd94\uc815 \ub2a5\ub825"},
gyQ(){return"\ud53c\ub85c"},
gx9(){return"\ub0ae\uc74c"},
