uw(a){return"\uc624\ub298 "+a+" \uc644\ub8cc"},
uN(a,b){return b+" \ubaa9\ud45c\uc758 "+a+"%\uc5d0 \ub3c4\ub2ec\ud588\uc5b4\uc694."},
uy(a){return a+" \ubaa9\ud45c\ub97c \ub2ec\uc131\ud588\uc5b4\uc694."},
